using System.Text;

namespace MapStudio.Core.Omsi.Models;

public sealed class OmsiO3dGeometryReader
{
    private const byte VertexSection = 0x17;
    private const byte TriangleSection = 0x49;
    private const byte MaterialSection = 0x26;
    private const byte BoneSection = 0x54;
    private const byte TransformSection = 0x79;

    private const uint MaxVertices = 150_000;
    private const uint MaxTriangles = 300_000;
    private const ushort MaxMaterials = 4_096;

    private static readonly Encoding Windows1252 =
        CreateWindows1252();

    public OmsiO3dGeometry Read(string path)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(path);

        if (!File.Exists(path))
        {
            return OmsiO3dGeometry.Error("missingFile");
        }

        try
        {
            using var stream = new FileStream(
                path,
                FileMode.Open,
                FileAccess.Read,
                FileShare.Read);

            using var reader = new BinaryReader(stream);

            if (!HasRemaining(stream, 3))
            {
                return OmsiO3dGeometry.Error("truncatedHeader");
            }

            if (reader.ReadByte() != 0x84 ||
                reader.ReadByte() != 0x19)
            {
                return OmsiO3dGeometry.Error("invalidSignature");
            }

            var version = reader.ReadByte();
            var longHeader = version > 3;
            var longTriangleIndices = false;

            if (longHeader)
            {
                if (!HasRemaining(stream, 5))
                {
                    return OmsiO3dGeometry.Error(
                        "truncatedExtendedHeader");
                }

                var options = reader.ReadByte();
                var encryptionKey = reader.ReadUInt32();

                longTriangleIndices =
                    (options & 0x01) != 0;

                if (encryptionKey != uint.MaxValue)
                {
                    return OmsiO3dGeometry.Error("encrypted");
                }
            }

            float[]? positions = null;
            float[]? normals = null;
            float[]? uvs = null;
            uint[]? indices = null;
            ushort[]? triangleMaterialIndices = null;
            IReadOnlyList<OmsiO3dMaterial> materials =
                Array.Empty<OmsiO3dMaterial>();

            uint vertexCount = 0;

            while (stream.Position < stream.Length)
            {
                var section = reader.ReadByte();

                switch (section)
                {
                    case VertexSection:
                        if (!TryReadCount(
                                reader,
                                longHeader,
                                out vertexCount))
                        {
                            return OmsiO3dGeometry.Error(
                                "invalidVertexSection");
                        }

                        if (vertexCount > MaxVertices)
                        {
                            return OmsiO3dGeometry.Error(
                                "tooManyVertices");
                        }

                        positions =
                            new float[checked((int)vertexCount * 3)];
                        normals =
                            new float[checked((int)vertexCount * 3)];
                        uvs =
                            new float[checked((int)vertexCount * 2)];

                        for (var index = 0U;
                             index < vertexCount;
                             index++)
                        {
                            if (!HasRemaining(stream, 32))
                            {
                                return OmsiO3dGeometry.Error(
                                    "invalidVertexSection");
                            }

                            var x = reader.ReadSingle();
                            var y = reader.ReadSingle();
                            var z = reader.ReadSingle();
                            var nx = reader.ReadSingle();
                            var ny = reader.ReadSingle();
                            var nz = reader.ReadSingle();
                            var u = reader.ReadSingle();
                            var v = reader.ReadSingle();

                            var p = checked((int)index * 3);
                            positions[p] = x;
                            positions[p + 1] = z;
                            positions[p + 2] = y;

                            normals[p] = nx;
                            normals[p + 1] = nz;
                            normals[p + 2] = ny;

                            var t = checked((int)index * 2);
                            uvs[t] = u;
                            uvs[t + 1] = 1 - v;
                        }
                        break;

                    case TriangleSection:
                        if (!TryReadCount(
                                reader,
                                longHeader,
                                out var triangleCount))
                        {
                            return OmsiO3dGeometry.Error(
                                "invalidTriangleSection");
                        }

                        if (triangleCount > MaxTriangles)
                        {
                            return OmsiO3dGeometry.Error(
                                "tooManyTriangles");
                        }

                        indices =
                            new uint[checked((int)triangleCount * 3)];

                        triangleMaterialIndices =
                            new ushort[checked((int)triangleCount)];

                        for (var index = 0U;
                             index < triangleCount;
                             index++)
                        {
                            if (!HasRemaining(
                                    stream,
                                    longTriangleIndices ? 14 : 8))
                            {
                                return OmsiO3dGeometry.Error(
                                    "invalidTriangleSection");
                            }

                            uint a;
                            uint b;
                            uint c;

                            if (longTriangleIndices)
                            {
                                a = reader.ReadUInt32();
                                b = reader.ReadUInt32();
                                c = reader.ReadUInt32();
                            }
                            else
                            {
                                a = reader.ReadUInt16();
                                b = reader.ReadUInt16();
                                c = reader.ReadUInt16();
                            }

                            var materialIndex =
                                reader.ReadUInt16();

                            var t = checked((int)index * 3);
                            indices[t] = c;
                            indices[t + 1] = b;
                            indices[t + 2] = a;

                            triangleMaterialIndices[
                                checked((int)index)] =
                                materialIndex;
                        }
                        break;

                    case MaterialSection:
                        if (!TryReadMaterials(
                                reader,
                                stream,
                                out materials))
                        {
                            return OmsiO3dGeometry.Error(
                                "invalidMaterialSection");
                        }
                        break;

                    case BoneSection:
                        if (!SkipBones(
                                reader,
                                stream,
                                longHeader,
                                longTriangleIndices))
                        {
                            return OmsiO3dGeometry.Error(
                                "invalidBoneSection");
                        }
                        break;

                    case TransformSection:
                        if (!TrySkip(stream, 64))
                        {
                            return OmsiO3dGeometry.Error(
                                "invalidTransformSection");
                        }
                        break;

                    default:
                        return OmsiO3dGeometry.Error(
                            $"unexpectedSection_{section:X2}");
                }
            }

            if (positions is null ||
                normals is null ||
                uvs is null ||
                indices is null ||
                triangleMaterialIndices is null)
            {
                return OmsiO3dGeometry.Error(
                    "noRenderableGeometry");
            }

            foreach (var index in indices)
            {
                if (index >= vertexCount)
                {
                    return OmsiO3dGeometry.Error(
                        "triangleIndexOutOfRange");
                }
            }

            return new OmsiO3dGeometry(
                IsLoaded: true,
                ErrorCode: null,
                Positions: positions,
                Normals: normals,
                Uvs: uvs,
                Indices: indices,
                TriangleMaterialIndices:
                    triangleMaterialIndices,
                Materials: materials);
        }
        catch (EndOfStreamException)
        {
            return OmsiO3dGeometry.Error(
                "unexpectedEndOfFile");
        }
        catch (OverflowException)
        {
            return OmsiO3dGeometry.Error(
                "geometryTooLarge");
        }
    }

    private static bool TryReadMaterials(
        BinaryReader reader,
        Stream stream,
        out IReadOnlyList<OmsiO3dMaterial> materials)
    {
        materials = Array.Empty<OmsiO3dMaterial>();

        if (!HasRemaining(stream, 2))
        {
            return false;
        }

        var materialCount = reader.ReadUInt16();

        if (materialCount > MaxMaterials)
        {
            return false;
        }

        var result =
            new List<OmsiO3dMaterial>(materialCount);

        for (var index = 0;
             index < materialCount;
             index++)
        {
            if (!HasRemaining(stream, 45))
            {
                return false;
            }

            var diffuseR = reader.ReadSingle();
            var diffuseG = reader.ReadSingle();
            var diffuseB = reader.ReadSingle();
            var diffuseA = reader.ReadSingle();

            var specularR = reader.ReadSingle();
            var specularG = reader.ReadSingle();
            var specularB = reader.ReadSingle();

            var emissionR = reader.ReadSingle();
            var emissionG = reader.ReadSingle();
            var emissionB = reader.ReadSingle();

            var specularPower = reader.ReadSingle();

            var textureLength = reader.ReadByte();

            if (!HasRemaining(
                    stream,
                    textureLength))
            {
                return false;
            }

            var textureName =
                textureLength == 0
                    ? null
                    : Windows1252.GetString(
                        reader.ReadBytes(
                            textureLength));

            result.Add(new OmsiO3dMaterial(
                diffuseR,
                diffuseG,
                diffuseB,
                diffuseA,
                specularR,
                specularG,
                specularB,
                emissionR,
                emissionG,
                emissionB,
                specularPower,
                string.IsNullOrWhiteSpace(
                    textureName)
                    ? null
                    : textureName));
        }

        materials = result;
        return true;
    }

    private static bool SkipBones(
        BinaryReader reader,
        Stream stream,
        bool longHeader,
        bool longTriangleIndices)
    {
        if (!TryReadCount(
                reader,
                longHeader,
                out var boneCount))
        {
            return false;
        }

        for (var index = 0U;
             index < boneCount;
             index++)
        {
            if (!HasRemaining(stream, 1))
            {
                return false;
            }

            var nameLength = reader.ReadByte();

            if (!TrySkip(stream, nameLength) ||
                !HasRemaining(stream, 2))
            {
                return false;
            }

            var weightCount = reader.ReadUInt16();
            var weightSize =
                longTriangleIndices ? 8L : 6L;

            if (!TrySkip(
                    stream,
                    checked((long)weightCount * weightSize)))
            {
                return false;
            }
        }

        return true;
    }

    private static bool TryReadCount(
        BinaryReader reader,
        bool longHeader,
        out uint count)
    {
        count = 0;
        var bytes = longHeader ? 4 : 2;

        if (!HasRemaining(reader.BaseStream, bytes))
        {
            return false;
        }

        count = longHeader
            ? reader.ReadUInt32()
            : reader.ReadUInt16();

        return true;
    }

    private static bool TrySkip(
        Stream stream,
        long bytes)
    {
        if (!HasRemaining(stream, bytes))
        {
            return false;
        }

        stream.Seek(bytes, SeekOrigin.Current);
        return true;
    }

    private static bool HasRemaining(
        Stream stream,
        long bytes) =>
        bytes >= 0 &&
        stream.Position <= stream.Length - bytes;

    private static Encoding CreateWindows1252()
    {
        Encoding.RegisterProvider(
            CodePagesEncodingProvider.Instance);

        return Encoding.GetEncoding(1252);
    }
}

namespace MapStudio.Core.Omsi.Models;

public sealed record OmsiO3dHeader(
    bool Exists,
    bool IsValid,
    int? Version,
    bool HasExtendedHeader,
    bool UsesLongTriangleIndices,
    bool UsesAlternativeEncryptionSeed,
    bool IsEncrypted)
{
    public static OmsiO3dHeader Missing { get; } = new(
        Exists: false,
        IsValid: false,
        Version: null,
        HasExtendedHeader: false,
        UsesLongTriangleIndices: false,
        UsesAlternativeEncryptionSeed: false,
        IsEncrypted: false);
}

using System.Buffers.Binary;

namespace MapStudio.Core.Omsi.Models;

public sealed class OmsiO3dHeaderReader
{
    private const byte Signature0 = 0x84;
    private const byte Signature1 = 0x19;

    public async Task<OmsiO3dHeader> ReadAsync(
        string path,
        CancellationToken cancellationToken = default)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(path);

        if (!File.Exists(path))
        {
            return OmsiO3dHeader.Missing;
        }

        var buffer = new byte[8];

        await using var stream = new FileStream(
            path,
            FileMode.Open,
            FileAccess.Read,
            FileShare.Read,
            bufferSize: 4096,
            useAsync: true);

        var bytesRead = 0;

        while (bytesRead < buffer.Length)
        {
            var read = await stream.ReadAsync(
                buffer.AsMemory(
                    bytesRead,
                    buffer.Length - bytesRead),
                cancellationToken);

            if (read == 0)
            {
                break;
            }

            bytesRead += read;
        }

        if (bytesRead < 3 ||
            buffer[0] != Signature0 ||
            buffer[1] != Signature1)
        {
            return new OmsiO3dHeader(
                Exists: true,
                IsValid: false,
                Version: null,
                HasExtendedHeader: false,
                UsesLongTriangleIndices: false,
                UsesAlternativeEncryptionSeed: false,
                IsEncrypted: false);
        }

        var version = buffer[2];
        var hasExtendedHeader = version > 3;

        if (!hasExtendedHeader)
        {
            return new OmsiO3dHeader(
                Exists: true,
                IsValid: true,
                Version: version,
                HasExtendedHeader: false,
                UsesLongTriangleIndices: false,
                UsesAlternativeEncryptionSeed: false,
                IsEncrypted: false);
        }

        if (bytesRead < 8)
        {
            return new OmsiO3dHeader(
                Exists: true,
                IsValid: false,
                Version: version,
                HasExtendedHeader: true,
                UsesLongTriangleIndices: false,
                UsesAlternativeEncryptionSeed: false,
                IsEncrypted: false);
        }

        var options = buffer[3];
        var encryptionKey =
            BinaryPrimitives.ReadUInt32LittleEndian(
                buffer.AsSpan(4, 4));

        return new OmsiO3dHeader(
            Exists: true,
            IsValid: true,
            Version: version,
            HasExtendedHeader: true,
            UsesLongTriangleIndices:
                (options & 0x01) != 0,
            UsesAlternativeEncryptionSeed:
                (options & 0x02) != 0,
            IsEncrypted:
                encryptionKey != uint.MaxValue);
    }
}

namespace MapStudio.Core.Omsi.Models;

public sealed class OmsiO3dStructureReader
{
    private const byte VertexSection = 0x17;
    private const byte TriangleSection = 0x49;
    private const byte MaterialSection = 0x26;
    private const byte BoneSection = 0x54;
    private const byte TransformSection = 0x79;

    public OmsiO3dStructureSummary Read(
        string path)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(path);

        if (!File.Exists(path))
        {
            return OmsiO3dStructureSummary.Invalid(
                "missingFile");
        }

        using var stream = new FileStream(
            path,
            FileMode.Open,
            FileAccess.Read,
            FileShare.Read);

        using var reader = new BinaryReader(stream);

        if (stream.Length < 3)
        {
            return OmsiO3dStructureSummary.Invalid(
                "truncatedHeader");
        }

        if (reader.ReadByte() != 0x84 ||
            reader.ReadByte() != 0x19)
        {
            return OmsiO3dStructureSummary.Invalid(
                "invalidSignature");
        }

        var version = reader.ReadByte();
        var longHeader = version > 3;
        var longTriangleIndices = false;

        if (longHeader)
        {
            if (!HasRemaining(stream, 5))
            {
                return OmsiO3dStructureSummary.Invalid(
                    "truncatedExtendedHeader");
            }

            var options = reader.ReadByte();
            _ = reader.ReadUInt32();
            longTriangleIndices =
                (options & 0x01) != 0;
        }

        uint vertexCount = 0;
        uint triangleCount = 0;
        ushort materialCount = 0;
        uint boneCount = 0;
        var hasTransform = false;

        while (stream.Position < stream.Length)
        {
            var section = reader.ReadByte();

            switch (section)
            {
                case VertexSection:
                    if (!TryReadCount(
                            reader,
                            longHeader,
                            out vertexCount) ||
                        !TrySkip(
                            stream,
                            checked(
                                (long)vertexCount * 32)))
                    {
                        return OmsiO3dStructureSummary.Invalid(
                            "invalidVertexSection");
                    }
                    break;

                case TriangleSection:
                    if (!TryReadCount(
                            reader,
                            longHeader,
                            out triangleCount))
                    {
                        return OmsiO3dStructureSummary.Invalid(
                            "invalidTriangleSection");
                    }

                    var triangleSize =
                        longTriangleIndices
                            ? 14L
                            : 8L;

                    if (!TrySkip(
                            stream,
                            checked(
                                (long)triangleCount *
                                triangleSize)))
                    {
                        return OmsiO3dStructureSummary.Invalid(
                            "invalidTriangleSection");
                    }
                    break;

                case MaterialSection:
                    if (!HasRemaining(stream, 2))
                    {
                        return OmsiO3dStructureSummary.Invalid(
                            "invalidMaterialSection");
                    }

                    materialCount =
                        reader.ReadUInt16();

                    for (var index = 0;
                         index < materialCount;
                         index++)
                    {
                        if (!TrySkip(stream, 44) ||
                            !HasRemaining(stream, 1))
                        {
                            return OmsiO3dStructureSummary.Invalid(
                                "invalidMaterialSection");
                        }

                        var texturePathLength =
                            reader.ReadByte();

                        if (!TrySkip(
                                stream,
                                texturePathLength))
                        {
                            return OmsiO3dStructureSummary.Invalid(
                                "invalidMaterialSection");
                        }
                    }
                    break;

                case BoneSection:
                    if (!TryReadCount(
                            reader,
                            longHeader,
                            out boneCount))
                    {
                        return OmsiO3dStructureSummary.Invalid(
                            "invalidBoneSection");
                    }

                    for (uint index = 0;
                         index < boneCount;
                         index++)
                    {
                        if (!HasRemaining(stream, 1))
                        {
                            return OmsiO3dStructureSummary.Invalid(
                                "invalidBoneSection");
                        }

                        var nameLength =
                            reader.ReadByte();

                        if (!TrySkip(
                                stream,
                                nameLength) ||
                            !HasRemaining(stream, 2))
                        {
                            return OmsiO3dStructureSummary.Invalid(
                                "invalidBoneSection");
                        }

                        var weightCount =
                            reader.ReadUInt16();

                        var weightSize =
                            longTriangleIndices
                                ? 8L
                                : 6L;

                        if (!TrySkip(
                                stream,
                                checked(
                                    (long)weightCount *
                                    weightSize)))
                        {
                            return OmsiO3dStructureSummary.Invalid(
                                "invalidBoneSection");
                        }
                    }
                    break;

                case TransformSection:
                    if (!TrySkip(stream, 64))
                    {
                        return OmsiO3dStructureSummary.Invalid(
                            "invalidTransformSection");
                    }

                    hasTransform = true;
                    break;

                default:
                    return OmsiO3dStructureSummary.Invalid(
                        $"unexpectedSection_{section:X2}");
            }
        }

        return new OmsiO3dStructureSummary(
            IsParsed: true,
            VertexCount: vertexCount,
            TriangleCount: triangleCount,
            MaterialCount: materialCount,
            BoneCount: boneCount,
            HasTransform: hasTransform,
            ErrorCode: null);
    }

    private static bool TryReadCount(
        BinaryReader reader,
        bool longHeader,
        out uint count)
    {
        count = 0;
        var stream = reader.BaseStream;
        var required =
            longHeader ? 4 : 2;

        if (!HasRemaining(
                stream,
                required))
        {
            return false;
        }

        count = longHeader
            ? reader.ReadUInt32()
            : reader.ReadUInt16();

        return true;
    }

    private static bool TrySkip(
        Stream stream,
        long bytes)
    {
        if (!HasRemaining(stream, bytes))
        {
            return false;
        }

        stream.Seek(
            bytes,
            SeekOrigin.Current);

        return true;
    }

    private static bool HasRemaining(
        Stream stream,
        long bytes) =>
        bytes >= 0 &&
        stream.Position <=
            stream.Length - bytes;
}

