namespace MapStudio.Core.Omsi.Scenery;

public static class OmsiSceneryMeshPathResolver
{
    private static readonly string[] SupportedExtensions =
        [".o3d", ".x"];

    public static bool TryResolve(
        string omsiRoot,
        string sceneryObjectFullPath,
        string declaredMeshPath,
        out string fullPath)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(omsiRoot);
        ArgumentException.ThrowIfNullOrWhiteSpace(sceneryObjectFullPath);
        ArgumentException.ThrowIfNullOrWhiteSpace(declaredMeshPath);

        fullPath = string.Empty;

        var extension = Path.GetExtension(declaredMeshPath);

        if (!SupportedExtensions.Contains(
                extension,
                StringComparer.OrdinalIgnoreCase))
        {
            return false;
        }

        var trimmed = declaredMeshPath.Trim();

        if (trimmed.Contains(':', StringComparison.Ordinal) ||
            trimmed.StartsWith(@"\\", StringComparison.Ordinal) ||
            trimmed.StartsWith("//", StringComparison.Ordinal))
        {
            return false;
        }

        try
        {
            var sceneryRoot = Path
                .GetFullPath(Path.Combine(omsiRoot, "Sceneryobjects"))
                .TrimEnd(
                    Path.DirectorySeparatorChar,
                    Path.AltDirectorySeparatorChar);

            var objectDirectory =
                Path.GetDirectoryName(
                    Path.GetFullPath(sceneryObjectFullPath));

            if (string.IsNullOrWhiteSpace(objectDirectory))
            {
                return false;
            }

            var normalized = trimmed
                .Replace('\\', Path.DirectorySeparatorChar)
                .Replace('/', Path.DirectorySeparatorChar)
                .TrimStart(
                    Path.DirectorySeparatorChar,
                    Path.AltDirectorySeparatorChar);

            var candidate = Path.GetFullPath(
                Path.Combine(
                    objectDirectory,
                    "model",
                    normalized));

            var requiredPrefix =
                sceneryRoot + Path.DirectorySeparatorChar;

            if (!candidate.StartsWith(
                    requiredPrefix,
                    StringComparison.OrdinalIgnoreCase))
            {
                return false;
            }

            fullPath = candidate;
            return true;
        }
        catch (Exception exception) when (
            exception is ArgumentException or
            NotSupportedException or
            PathTooLongException)
        {
            return false;
        }
    }
}

namespace MapStudio.Core.Omsi.Scenery;

public static class OmsiSceneryObjectPathResolver
{
    private const string SceneryDirectoryName = "Sceneryobjects";

    public static bool TryResolve(
        string omsiRoot,
        string sceneryObjectPath,
        out string fullPath)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(omsiRoot);
        ArgumentException.ThrowIfNullOrWhiteSpace(sceneryObjectPath);

        fullPath = string.Empty;

        if (!string.Equals(
                Path.GetExtension(sceneryObjectPath),
                ".sco",
                StringComparison.OrdinalIgnoreCase) ||
            Path.IsPathRooted(sceneryObjectPath))
        {
            return false;
        }

        try
        {
            var sceneryRoot = Path
                .GetFullPath(Path.Combine(omsiRoot, SceneryDirectoryName))
                .TrimEnd(
                    Path.DirectorySeparatorChar,
                    Path.AltDirectorySeparatorChar);

            var normalized = sceneryObjectPath
                .Replace('\\', Path.DirectorySeparatorChar)
                .Replace('/', Path.DirectorySeparatorChar)
                .TrimStart(
                    Path.DirectorySeparatorChar,
                    Path.AltDirectorySeparatorChar);

            var sceneryPrefix =
                SceneryDirectoryName + Path.DirectorySeparatorChar;

            if (normalized.StartsWith(
                    sceneryPrefix,
                    StringComparison.OrdinalIgnoreCase))
            {
                normalized = normalized[sceneryPrefix.Length..];
            }

            var candidate = Path.GetFullPath(
                Path.Combine(sceneryRoot, normalized));

            var requiredPrefix =
                sceneryRoot + Path.DirectorySeparatorChar;

            if (!candidate.StartsWith(
                    requiredPrefix,
                    StringComparison.OrdinalIgnoreCase))
            {
                return false;
            }

            fullPath = candidate;
            return true;
        }
        catch (Exception exception) when (
            exception is ArgumentException or
            NotSupportedException or
            PathTooLongException)
        {
            return false;
        }
    }
}

using System.Globalization;
using MapStudio.Core.Omsi.Config;

namespace MapStudio.Core.Omsi.Scenery;

public sealed class OmsiSceneryObjectReader
{
    public async Task<OmsiSceneryObjectMetadata> ReadMetadataAsync(
        string sceneryObjectPath,
        CancellationToken cancellationToken = default)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(sceneryObjectPath);

        if (!File.Exists(sceneryObjectPath))
        {
            return OmsiSceneryObjectMetadata.Missing;
        }

        var document = await OmsiConfigParser.ParseFileAsync(
            sceneryObjectPath,
            cancellationToken);

        return ReadMetadata(document);
    }

    public static OmsiSceneryObjectMetadata ReadMetadata(
        OmsiConfigDocument document)
    {
        ArgumentNullException.ThrowIfNull(document);

        var friendlyName = document
            .FindFirstSection("friendlyname")
            ?.DataLines
            .FirstOrDefault();

        var groups = ReadGroups(document);
        var meshes = ReadMeshes(document);
        var collisionMeshes = ReadSingleValueSections(
            document,
            "collision_mesh");

        var materialOverrides =
            ReadMaterialOverrides(
                document);

        return new OmsiSceneryObjectMetadata(
            Exists: true,
            FriendlyName: friendlyName,
            Groups: groups,
            MeshPaths: meshes.Paths,
            MeshLodThresholds:
                meshes.LodThresholds,
            CollisionMeshPaths: collisionMeshes,
            MaterialOverrides:
                materialOverrides);
    }

    private static MeshReadResult
        ReadMeshes(
            OmsiConfigDocument document)
    {
        var paths =
            new List<string>();

        var lodThresholds =
            new List<double?>();

        double? currentLodThreshold =
            null;

        foreach (var section in
            document.Sections)
        {
            if (string.Equals(
                    section.Keyword,
                    "LOD",
                    StringComparison.OrdinalIgnoreCase))
            {
                currentLodThreshold =
                    null;

                var value =
                    section.DataLines
                        .FirstOrDefault();

                if (
                    double.TryParse(
                        value,
                        NumberStyles.Float,
                        CultureInfo.InvariantCulture,
                        out var threshold) &&
                    double.IsFinite(threshold) &&
                    threshold >= 0)
                {
                    currentLodThreshold =
                        threshold;
                }

                continue;
            }

            if (!string.Equals(
                    section.Keyword,
                    "mesh",
                    StringComparison.OrdinalIgnoreCase))
            {
                continue;
            }

            var path =
                section.DataLines
                    .FirstOrDefault();

            if (string.IsNullOrWhiteSpace(
                    path))
            {
                continue;
            }

            paths.Add(path);
            lodThresholds.Add(
                currentLodThreshold);
        }

        return new MeshReadResult(
            paths,
            lodThresholds);
    }

    private static IReadOnlyList<
        OmsiSceneryMaterialOverride>
        ReadMaterialOverrides(
            OmsiConfigDocument document)
    {
        var result =
            new List<MaterialOverrideBuilder>();

        var meshOrdinal = -1;

        MaterialOverrideBuilder?
            current = null;

        foreach (var section in
            document.Sections)
        {
            if (string.Equals(
                    section.Keyword,
                    "mesh",
                    StringComparison.OrdinalIgnoreCase))
            {
                meshOrdinal++;
                current = null;
                continue;
            }

            if (string.Equals(
                    section.Keyword,
                    "matl_change",
                    StringComparison.OrdinalIgnoreCase))
            {
                current = null;
                continue;
            }

            if (string.Equals(
                    section.Keyword,
                    "matl",
                    StringComparison.OrdinalIgnoreCase))
            {
                current = null;

                if (meshOrdinal < 0)
                {
                    continue;
                }

                var values =
                    section.DataLines
                        .ToArray();

                if (
                    values.Length < 2 ||
                    string.IsNullOrWhiteSpace(
                        values[0]) ||
                    !int.TryParse(
                        values[1],
                        NumberStyles.Integer,
                        CultureInfo.InvariantCulture,
                        out var materialIndex) ||
                    materialIndex < 0)
                {
                    continue;
                }

                current =
                    new MaterialOverrideBuilder(
                        meshOrdinal,
                        values[0],
                        materialIndex);

                result.Add(current);
                continue;
            }

            if (current is null)
            {
                continue;
            }

            if (string.Equals(
                    section.Keyword,
                    "matl_alpha",
                    StringComparison.OrdinalIgnoreCase))
            {
                var value =
                    section.DataLines
                        .FirstOrDefault();

                if (
                    int.TryParse(
                        value,
                        NumberStyles.Integer,
                        CultureInfo.InvariantCulture,
                        out var alphaMode) &&
                    alphaMode is >= 0 and <= 2)
                {
                    current.AlphaMode =
                        alphaMode;
                }

                continue;
            }

            if (string.Equals(
                    section.Keyword,
                    "matl_transmap",
                    StringComparison.OrdinalIgnoreCase))
            {
                var source =
                    section.DataLines
                        .FirstOrDefault();

                if (!string.IsNullOrWhiteSpace(
                        source))
                {
                    current.TransMapSource =
                        source;
                }

                continue;
            }

            if (string.Equals(
                    section.Keyword,
                    "matl_lightmap",
                    StringComparison.OrdinalIgnoreCase))
            {
                var textureName =
                    section.DataLines
                        .FirstOrDefault();

                if (!string.IsNullOrWhiteSpace(
                        textureName))
                {
                    current.LightMapTextureName =
                        textureName;
                }

                continue;
            }

            if (string.Equals(
                    section.Keyword,
                    "matl_envmap",
                    StringComparison.OrdinalIgnoreCase))
            {
                var values =
                    section.DataLines
                        .ToArray();

                if (
                    values.Length > 0 &&
                    !string.IsNullOrWhiteSpace(
                        values[0]))
                {
                    current
                        .EnvironmentMapTextureName =
                        values[0];
                }

                if (
                    values.Length > 1 &&
                    double.TryParse(
                        values[1],
                        NumberStyles.Float,
                        CultureInfo.InvariantCulture,
                        out var strength) &&
                    double.IsFinite(strength))
                {
                    current
                        .EnvironmentMapStrength =
                        strength;
                }

                continue;
            }

            if (string.Equals(
                    section.Keyword,
                    "matl_nightmap",
                    StringComparison.OrdinalIgnoreCase))
            {
                var textureName =
                    section.DataLines
                        .FirstOrDefault();

                if (!string.IsNullOrWhiteSpace(
                        textureName))
                {
                    current.NightMapTextureName =
                        textureName;
                }

                continue;
            }

            if (string.Equals(
                    section.Keyword,
                    "matl_bumpmap",
                    StringComparison.OrdinalIgnoreCase))
            {
                var values =
                    section.DataLines
                        .ToArray();

                if (
                    values.Length > 0 &&
                    !string.IsNullOrWhiteSpace(
                        values[0]))
                {
                    current.BumpMapTextureName =
                        values[0];
                }

                if (
                    values.Length > 1 &&
                    double.TryParse(
                        values[1],
                        NumberStyles.Float,
                        CultureInfo.InvariantCulture,
                        out var strength) &&
                    double.IsFinite(strength))
                {
                    current.BumpMapStrength =
                        strength;
                }

                continue;
            }

            if (
                string.Equals(
                    section.Keyword,
                    "matl_envmap_mask",
                    StringComparison.OrdinalIgnoreCase) ||
                string.Equals(
                    section.Keyword,
                    "alphascale",
                    StringComparison.OrdinalIgnoreCase) ||
                string.Equals(
                    section.Keyword,
                    "matl_allcolor",
                    StringComparison.OrdinalIgnoreCase))
            {
                current.UnsupportedCommands
                    .Add(
                        "[" +
                        section.Keyword +
                        "]");

                continue;
            }

            if (string.Equals(
                    section.Keyword,
                    "matl_noZwrite",
                    StringComparison.OrdinalIgnoreCase))
            {
                current.NoZWrite = true;
                continue;
            }

            if (string.Equals(
                    section.Keyword,
                    "matl_noZcheck",
                    StringComparison.OrdinalIgnoreCase))
            {
                current.NoZCheck = true;
            }
        }

        return result
            .Select(
                builder =>
                    new OmsiSceneryMaterialOverride(
                        builder.MeshOrdinal,
                        builder.TextureName,
                        builder.MaterialIndex,
                        builder.AlphaMode,
                        builder.NoZWrite,
                        builder.NoZCheck,
                        builder.BumpMapTextureName,
                        builder.BumpMapStrength,
                        builder.NightMapTextureName,
                        builder.EnvironmentMapTextureName,
                        builder.EnvironmentMapStrength,
                        builder.TransMapSource,
                        builder.LightMapTextureName,
                        builder.UnsupportedCommands
                            .Distinct(
                                StringComparer.OrdinalIgnoreCase)
                            .ToArray()))
            .ToArray();
    }

    private static IReadOnlyList<string> ReadGroups(
        OmsiConfigDocument document)
    {
        var values = document
            .FindFirstSection("groups")
            ?.DataLines
            .ToArray();

        if (values is null ||
            values.Length == 0 ||
            !int.TryParse(
                values[0],
                NumberStyles.Integer,
                CultureInfo.InvariantCulture,
                out var count) ||
            count <= 0)
        {
            return Array.Empty<string>();
        }

        return values
            .Skip(1)
            .Take(count)
            .ToArray();
    }

    private static IReadOnlyList<string> ReadSingleValueSections(
        OmsiConfigDocument document,
        string keyword) =>
        document
            .FindSections(keyword)
            .Select(section => section.DataLines.FirstOrDefault())
            .Where(static value => !string.IsNullOrWhiteSpace(value))
            .Select(static value => value!)
            .ToArray();

    private sealed record MeshReadResult(
        IReadOnlyList<string> Paths,
        IReadOnlyList<double?> LodThresholds);

    private sealed class MaterialOverrideBuilder(
        int meshOrdinal,
        string textureName,
        int materialIndex)
    {
        public int MeshOrdinal { get; } =
            meshOrdinal;

        public string TextureName { get; } =
            textureName;

        public int MaterialIndex { get; } =
            materialIndex;

        public int? AlphaMode { get; set; }

        public bool NoZWrite { get; set; }

        public bool NoZCheck { get; set; }

        public string?
            BumpMapTextureName
        { get; set; }

        public double?
            BumpMapStrength
        { get; set; }

        public string?
            NightMapTextureName
        { get; set; }

        public string?
            EnvironmentMapTextureName
        { get; set; }

        public double?
            EnvironmentMapStrength
        { get; set; }

        public string?
            TransMapSource
        { get; set; }

        public string?
            LightMapTextureName
        { get; set; }

        public List<string>
            UnsupportedCommands
        { get; } = [];
    }
}

namespace MapStudio.Core.Omsi.Splines;

public sealed record OmsiSplineDefinition(
    bool Exists,
    IReadOnlyList<string> Textures,
    IReadOnlyList<OmsiSplineSurface> Surfaces)
{
    public static OmsiSplineDefinition Missing { get; } = new(
        Exists: false,
        Textures: Array.Empty<string>(),
        Surfaces: Array.Empty<OmsiSplineSurface>());
}

using System.Globalization;
using MapStudio.Core.Omsi.Config;

namespace MapStudio.Core.Omsi.Splines;

public sealed class OmsiSplineDefinitionReader
{
    public async Task<OmsiSplineDefinition> ReadAsync(
        string path,
        CancellationToken cancellationToken = default)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(path);

        if (!File.Exists(path))
        {
            return OmsiSplineDefinition.Missing;
        }

        var document =
            await OmsiConfigParser.ParseFileAsync(
                path,
                cancellationToken);

        return Read(document);
    }

    public OmsiSplineDefinition Read(
        OmsiConfigDocument document)
    {
        ArgumentNullException.ThrowIfNull(document);

        var textures =
            document.FindSections("texture")
                .Select(
                    static section =>
                        section.DataLines
                            .FirstOrDefault())
                .Where(
                    static value =>
                        !string.IsNullOrWhiteSpace(
                            value))
                .Select(
                    static value =>
                        value!)
                .ToArray();

        var surfaces =
            new List<OmsiSplineSurface>();

        for (
            var index = 0;
            index < document.Sections.Count;
            index++)
        {
            var section =
                document.Sections[index];

            if (!string.Equals(
                    section.Keyword,
                    "profile",
                    StringComparison.OrdinalIgnoreCase))
            {
                continue;
            }

            var textureValue =
                section.DataLines
                    .FirstOrDefault();

            if (!int.TryParse(
                    textureValue,
                    NumberStyles.Integer,
                    CultureInfo.InvariantCulture,
                    out var textureIndex) ||
                textureIndex < 0)
            {
                continue;
            }

            var points =
                new List<OmsiSplineProfilePoint>(
                    capacity: 2);

            for (
                var nextIndex = index + 1;
                nextIndex < document.Sections.Count &&
                points.Count < 2;
                nextIndex++)
            {
                var next =
                    document.Sections[nextIndex];

                if (string.Equals(
                        next.Keyword,
                        "profile",
                        StringComparison.OrdinalIgnoreCase))
                {
                    break;
                }

                if (!string.Equals(
                        next.Keyword,
                        "profilepnt",
                        StringComparison.OrdinalIgnoreCase))
                {
                    continue;
                }

                var point =
                    TryReadPoint(next);

                if (point is not null)
                {
                    points.Add(point);
                }
            }

            if (points.Count != 2)
            {
                continue;
            }

            surfaces.Add(
                new OmsiSplineSurface(
                    TextureIndex:
                        textureIndex,
                    TextureName:
                        textureIndex <
                            textures.Length
                            ? textures[
                                textureIndex]
                            : null,
                    From: points[0],
                    To: points[1]));
        }

        return new OmsiSplineDefinition(
            Exists: true,
            Textures: textures,
            Surfaces: surfaces);
    }

    private static OmsiSplineProfilePoint?
        TryReadPoint(
            OmsiConfigSection section)
    {
        var values =
            section.DataLines
                .Take(4)
                .ToArray();

        if (values.Length < 4 ||
            !TryParseDouble(
                values[0],
                out var x) ||
            !TryParseDouble(
                values[1],
                out var z) ||
            !TryParseDouble(
                values[2],
                out var textureX) ||
            !TryParseDouble(
                values[3],
                out var textureScale))
        {
            return null;
        }

        return new OmsiSplineProfilePoint(
            X: x,
            Z: z,
            TextureX: textureX,
            TextureScale: textureScale);
    }

    private static bool TryParseDouble(
        string value,
        out double result) =>
        double.TryParse(
            value,
            NumberStyles.Float,
            CultureInfo.InvariantCulture,
            out result);
}

namespace MapStudio.Core.Omsi.Splines;

public static class OmsiSplinePathResolver
{
    public static bool TryResolve(
        string omsiRoot,
        string declaredSplinePath,
        out string fullPath)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(omsiRoot);
        ArgumentException.ThrowIfNullOrWhiteSpace(declaredSplinePath);

        fullPath = string.Empty;

        var trimmed =
            declaredSplinePath.Trim();

        if (!string.Equals(
                Path.GetExtension(trimmed),
                ".sli",
                StringComparison.OrdinalIgnoreCase) ||
            trimmed.Contains(
                ':',
                StringComparison.Ordinal) ||
            trimmed.StartsWith(
                @"\\",
                StringComparison.Ordinal) ||
            trimmed.StartsWith(
                "//",
                StringComparison.Ordinal))
        {
            return false;
        }

        try
        {
            var splinesRoot = Path
                .GetFullPath(
                    Path.Combine(
                        omsiRoot,
                        "Splines"))
                .TrimEnd(
                    Path.DirectorySeparatorChar,
                    Path.AltDirectorySeparatorChar);

            var normalized =
                trimmed
                    .Replace(
                        '\\',
                        Path.DirectorySeparatorChar)
                    .Replace(
                        '/',
                        Path.DirectorySeparatorChar)
                    .TrimStart(
                        Path.DirectorySeparatorChar,
                        Path.AltDirectorySeparatorChar);

            var splinesPrefix =
                "Splines" +
                Path.DirectorySeparatorChar;

            if (normalized.StartsWith(
                    splinesPrefix,
                    StringComparison.OrdinalIgnoreCase))
            {
                normalized =
                    normalized[
                        splinesPrefix.Length..];
            }

            var candidate =
                Path.GetFullPath(
                    Path.Combine(
                        splinesRoot,
                        normalized));

            var requiredPrefix =
                splinesRoot +
                Path.DirectorySeparatorChar;

            if (!candidate.StartsWith(
                    requiredPrefix,
                    StringComparison.OrdinalIgnoreCase))
            {
                return false;
            }

            fullPath = candidate;
            return true;
        }
        catch (Exception exception) when (
            exception is ArgumentException or
            NotSupportedException or
            PathTooLongException)
        {
            return false;
        }
    }
}
